def process(reportsByMilitaryConsumers, reportCategories) -> pd.DataFrame:
    import pandas as pd

    # Military % of Imposter Scams (requires detailed category breakdown; not available here).
    # So answer is based on available: general population % of Imposter Scams from reportCategories,
    # and military table does not provide Imposter Scams at all.
    gen_imposter_pct = reportCategories.loc[
        reportCategories["category"].astype(str).str.strip().str.lower().eq("imposter scams"),
        "percentage",
    ]
    gen_imposter_pct = float(gen_imposter_pct.iloc[0]) if len(gen_imposter_pct) else float("nan")

    military_has_imposter = reportsByMilitaryConsumers["reportType"].astype(str).str.strip().str.lower().eq(
        "imposter scams"
    ).any()

    # If military percentage cannot be computed, return No by default.
    return pd.DataFrame(
        [
            {
                "genImposterPct": gen_imposter_pct,
                "militaryHasImposterRow": bool(military_has_imposter),
                "answer": "No",
            }
        ]
    )
